def transform(grid):
    out=[row[:] for row in grid]
    H,W=len(grid),len(grid[0])
    boxes=[]
    for color in range(1,10):
        pts=[(r,c) for r in range(H) for c in range(W) if grid[r][c]==color]
        if not pts: continue
        r0=min(r for r,c in pts); r1=max(r for r,c in pts)
        c0=min(c for r,c in pts); c1=max(c for r,c in pts)
        if all(grid[r0][c]==grid[r1][c]==color for c in range(c0,c1+1)) and all(grid[r][c0]==grid[r][c1]==color for r in range(r0,r1+1)):
            boxes.append((color,r0,r1,c0,c1))
    for sc,r0,r1,c0,c1 in boxes:
        src=[[grid[r][c] for c in range(c0+1,c1)] for r in range(r0+1,r1)]
        if not any(v==sc for row in src for v in row): continue
        h,w=r1-r0-1,c1-c0-1
        for dc,a,b,x,y in boxes:
            if dc==sc or b-a-1!=h or y-x-1!=w: continue
            if any(grid[r][c]!=0 for r in range(a+1,b) for c in range(x+1,y)): continue
            for i in range(h):
                for j in range(w):
                    if src[i][j]==sc: out[a+1+i][x+1+j]=dc
    return out

